package com.netflix.zuul.netty;

import static com.netflix.zuul.exception.ErrorType.NO_AVAILABLE_SERVERS;
import static com.netflix.zuul.exception.ErrorType.OTHER;
import static com.netflix.zuul.exception.ErrorType.RESET_CONNECTION;

