import sun.nio.ch.SocketOpts.OptionKey;
import sun.nio.ch.SocketOpts.TCP;
import sun.nio.ch.SocketOpts.UnixDomain;

public class NettyRequestAttemptFactory {

  private static final InternalLogger LOG =
      InternalLoggerFactory.getInstance(NettyRequestAttemptFactory.class);

  public ErrorType mapNettyToOutboundErrorType(final Throwable t) {
    if (t instanceof ReadTimeoutException) {
      return ErrorType.READ_TIMEOUT;
    }

    if (t instanceof WriteTimeoutException) {
      return ErrorType.WRITE_TIMEOUT;
    }

    if (t instanceof ConnectException) {
      return ErrorType.CONNECT_ERROR;
    }

    if (t instanceof OriginConnectException) {
      return ((OriginConnectException) t).getErrorType();
    }

    if (t instanceof OutboundException) {
      return ((OutboundException) t).getOutboundErrorType();
    }

    if (t instanceof io.netty.channel.unix.Errors.NativeIoException
        && io.netty.channel.unix.Errors.ERRNO_ECONNRESET_NEGATIVE
            == ((io.netty.channel.unix.Errors.NativeIoException) t).expectedErr()) {
      // This is a "Connection reset by peer" which we see fairly often happening when Origin
      // servers are overloaded.
      LOG.warn("ERRNO_ECONNRESET_NEGATIVE mapped to RESET_CONNECTION", t);
      return RESET_CONNECTION;
    }

    if (t instanceof ClosedChannelException) {
      return RESET_CONNECTION;
    }

    final Throwable cause = t.getCause();
    if (cause != null
        && cause instanceof IllegalStateException
        && cause.getMessage() != null
        && cause.getMessage().contains("server")) {
      LOG.warn("IllegalStateException mapped to NO_AVAILABLE_SERVERS", cause);
      return NO_AVAILABLE_SERVERS;
    }

    return OTHER;
  }

  public OutboundException mapNettyToOutboundException(
      final Throwable t, final SessionContext context) {
    if (t instanceof OutboundException) {
      return (OutboundException) t;
    }

    // Map this throwable to zuul's OutboundException.
    final ErrorType errorType = mapNettyToOutboundErrorType(t);
    final RequestAttempts attempts = RequestAttempts.getFromSessionContext(context);
    if (errorType == OTHER) {
      return new OutboundException(errorType, attempts, t);
    }
    return new OutboundException(errorType, attempts);
  }
}
